	title 'QD ENV               GS ROM 3.0'*****************************************************************			   **              ENV			   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	blanks off	string asis***	include 'all.macros'	;removed 17-Sep-90 DAL	include 'm16.util2'	include 'm16.quickdraw'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC0	IMPORT BusyEC2	IMPORT BusyEC4	IMPORT BusyEC6	IMPORT BusyErr4	IMPORT ConTable320	IMPORT ConTable640	IMPORT EndCall4	IMPORT EndCall6	IMPORT ErrOut4	IMPORT ErrOut6	IMPORT HideCursor	IMPORT Port320	IMPORT Port640	IMPORT QDStart	IMPORT ShowCursor	IMPORT StandardPort	IMPORT StdPnState	IMPORT Table320	IMPORT Table640	IMPORT WideOpen	IMPORT oEndCall0	IMPORT oEndCall2	IMPORT oEndCall4	IMPORT oEndCall6	IMPORT oErrOut2	IMPORT oErrOut4	IMPORT oErrOut6;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY ExpandM320	ENTRY ExpandM640	ENTRY ExtendColorWord	ENTRY InitThePort	ENTRY MakeSolid	ENTRY UserMask2ZP	ENTRY ZP2Back	ENTRY ZP2Mask	ENTRY ZP2Pen	ENTRY ZP2PortLoc	ENTRY ZP2UserMask	ENTRY ZP2UserPat****************************************************************** ENV.CALLS** This file contains routines to manipulate the hardware* and set some global environment variables that are not part* of the GrafPort.**** GrafOn* GrafOff* StandardSCB* InitColorTable* SetColorTable* GetColorTable		; modified 2 Apr 86	(now works out*		; of bank 0)* SetColorEntry* GetColorEntry* SetSCB* GetSCB* SetAllSCBs* ClearScreen* GetMasterSCB* SetMasterSCB******************************************************************* The following macro should be used by any routine that changes the zeropage pattern* holder, the penpat or the back pat...	MACRO	DirtyPatterns	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #AllPatsBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND		MACRO	DirtyPort	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PortBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND			MACRO	DirtyMask	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PenMaskBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND		MACRO	DirtyDrawState	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #DrawStateBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND****************************************************************** GrafOn** Turns on the SuperHiRes graphics and linearizes the* memory.*****************************************************************	EXPORT GrafOnGrafOn	PROC	sep #%00110000	longa off	longi off	lda #%10000000	ora >$E0C029	sta >$E0C029	rep #%00110000	longa on	longi on	jmp oEndCall0	ENDP****************************************************************** GrafOff** Turns off the SuperHiRes graphics and	de-linearizes the* memory.*****************************************************************	EXPORT GrafOffGrafOff	PROC	sep #%00110000	longa off	longi off	lda #%01111111	and >$E0C029	sta >$E0C029	rep #%00110000	longa on	longi on	jmp oEndCall0	ENDP****************************************************************** GetStandardSCB** Returns the Standard SCB on the stack.*****************************************************************	EXPORT GetStandardSCBGetStandardSCB	PROC	lda #StandardSCB	sta 7,s	jmp oEndCall0	ENDP****************************************************************** InitColorTable  (TablePtr : Ptr)** Fills the specified color table with the standard* color table.*****************************************************************	EXPORT InitColorTableInitColorTable	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TableRef	equ RTL2+3	jsr QDStart	lda TableRef,s	; move this pointer	to zp	sta Temp	lda TableRef+1,s	sta Temp+1	bit MasterSCB-1	bmi Do640	ldy #ColorTableSize-2Loop1	tyx	lda >Table320,x	sta [Temp],y	dey	dey	bpl loop1	bra AllDoneDo640		; 	ldy #ColorTableSize-2Loop2	tyx	lda >Table640,x	sta [Temp],y	dey	dey	bpl loop2AllDone	jmp BusyEC4	ENDP****************************************************************** SetColorTable (TableNumber : integer;	TablePtr : Ptr);** Parameter block is set up as follows:*        TableNumber : word*        TableRef	 : adr*** Modification History**     24 April 86	   Error checking on table number added*****************************************************************	EXPORT SetColorTableSetColorTable	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TableRef	equ RTL2+3TableNum	equ TableRef+4	phd	tsc	; get stack pointer	tcd	; make it zp* now compute address of table	lda #ColorTableSize-2 ; start with this	in a-reg	ldx TableNum	; get table num	beq Done	; if zero done	cpx #16	bcs errorLoop	clc	; add table size table num times	adc #ColorTableSize	dex	bne LoopDone	tax	ldy #ColorTableSize-2MoveLoop	lda [TableRef],y	sta >FirstTable,x	dex	dex	dey	dey	bpl MoveLoop	jmp EndCall6error	ldx #BadTableNum	jmp ErrOut6	ENDP****************************************************************** GetColorTable   (TableNum : integer; TablePtr : Ptr);** Modification History**   2 Apr 86    SEG	   TableNum equate was off by 2.*  24 Apr 86    SEG	   Error check for table number added.*****************************************************************	EXPORT GetColorTableGetColorTable	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TableRef	equ RTL2+3TableNum	equ TableRef+4	phd	tsc	; get stack pointer	tcd	; make it zp* now compute address of table	lda #ColorTableSize-2	ldx TableNum	beq done	cpx #16	bcs errorLoop	clc	adc #ColorTableSize	dex	bne LoopDone	tax	ldy #ColorTableSize-2MoveLoop	lda >FirstTable,x	sta [TableRef],y	dex	dex	dey	dey	bpl MoveLoop	jmp EndCall6error	ldx #BadTableNum	jmp ErrOut6	ENDP****************************************************************** SetColorEntry (TableNum, ColorNum, NewColor : integer);** Modification History**     24 April 86	   Error checking on TableNum and*	   ColorNum added*****************************************************************	EXPORT SetColorEntrySetColorEntry	PROCRTL1	equ 1RTL2	equ RTL1+3NewColor	equ RTL2+3ColorNum	equ NewColor+2TableNum	equ ColorNum+2	lda TableNum,s	; start by getting adr of table	cmp #16	bcs error1	tay	beq done	lda #0	clcLoop	adc #ColorTableSize	dey	bne LoopDone	tax	lda ColorNum,s	cmp #16	bcs error2	txa	adc ColorNum,s	; add the color number twice for	adc ColorNum,s	; additional offset	tax	lda NewColor,s	sta >FirstTable,x	jmp oEndCall6error1	ldx #BadTableNum	jmp oErrOut6error2	ldx #BadColorNum	jmp oErrOut6	ENDP****************************************************************** GetColorEntry   (TableNum, ColorNum :	integer) : integer;** Modification History**     24 April 86	   Error checking on TableNum and*	   ColorNum added*****************************************************************	EXPORT GetColorEntryGetColorEntry	PROCRTL1	equ 1RTL2	equ RTL1+3ColorNum	equ RTL2+3TableNum	equ ColorNum+2ColorResult	equ TableNum+2	lda TableNum,s	; start by getting adr of table	cmp #16	bcs error1	tay	beq done	lda #0	clcLoop	adc #ColorTableSize	dey	bne LoopDone	tax	lda ColorNum,s	cmp #16	bcs error2	txa	adc ColorNum,s	; add the color number twice for	adc ColorNum,s	; additional offset	tax	lda >FirstTable,x	sta ColorResult,s	jmp oEndCall4error1	ldx #BadTableNum	jmp oErrOut4error2	ldx #BadColorNum	jmp oErrOut4	ENDP****************************************************************** SetSCB   (ScanLine, Value : integer);** Modification History**     24 April 86	   Error checking on ScanLine number*****************************************************************	EXPORT SetSCBSetSCB	PROCRTL1	equ 1RTL2	equ RTL1+3NewValue	equ RTL2+3ScanLine	equ NewValue+2	lda ScanLine,s	cmp #200	bcs error	lda #0	; clear the a-reg so tax has high of 0	sep #%00100000	; 8 bit a-reg	longa off	lda ScanLine,s	tax	lda NewValue,s	sta >FirstSCB,x	rep #%00100000	; back to 16 bits	longa on	jmp oEndCall4error	ldx #BadScanLine	jmp oErrOut4	ENDP****************************************************************** GetSCB  (ScanLine	: integer) : integer;** Modification History**     24 April 86	   Error checking on ScanLine number*****************************************************************	EXPORT GetSCBGetSCB	PROCRTL1	equ 1RTL2	equ RTL1+3ScanLine	equ RTL2+3ResultValue	equ ScanLine+2	lda ScanLine,s	cmp #200	bcs error	lda #0	; clear a reg	sep #%00100000	; 8 bit a-reg	longa off	lda ScanLine,s	tax	lda >FirstSCB,x	sta ResultValue,s	rep #%00100000	; back to 16 bits	longa on	jmp oEndCall2error	ldx #BadScanLine	jmp oErrOut2	ENDP****************************************************************** SetAllSCBs   (NewValue : integer);*****************************************************************	EXPORT SetAllSCBsSetAllSCBs	PROCRTL1	equ 1RTL2	equ RTL1+3NewValue	equ RTL2+3	sep #%00100000	; 8 bit a-reg	longa off	lda NewValue,s	ldx #NumScanLinesLoop	sta >FirstSCB-1,x	dex	bne Loop	rep #%00110000	; back to 16 bits	longa on	jmp oEndCall2	ENDP****************************************************************** ClearScreen  (Color : integer);** Clears the super hi-res screen, setting all words to the* value passed.*** Modification History**  12 Feb 89    DDG	   This routine now checks for shadowing***  14 Feb 89    DDG	   Fixed a bug where I was reading the wrong*	   word on the stack for the color.*****************************************************************	EXPORT ClearScreenClearScreen	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Color	equ RTL2+3	jsr QDStart	jsl HideCursor	phb	; save bank register	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne @1	; if zero, then shadowing is on	pea $0101	; push on the shadowed bank	bra @2@1	pea $E1E1	; push this on stack@2	plb	; set bank twice to	plb	; clear stack	lda Color+1,s	ldx #160*200-2Loop	sta |ScreenBase,x	dex	dex	bpl Loop	plb	; get back bank address	tdc	; fake out tool locator call	jsl ShowCursor	jmp BusyEC2	ENDP****************************************************************** SetMasterSCB  (TheSCB : integer)** Sets the MasterSCB to the value passed*****************************************************************	EXPORT SetMasterSCBSetMasterSCB	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheValue	equ RTL2+3	jsr QDStart	lda TheValue,s	sta MasterSCB	jmp BusyEC2	ENDP****************************************************************** GetMasterSCB    :	integer** Returns the master SCB.*****************************************************************	EXPORT GetMasterSCBGetMasterSCB	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheValue	equ RTL2+3	jsr QDStart	lda MasterSCB	; use value on zero	page	sta TheValue,s	jmp BusyEC0	ENDP	PRINT OFF;                COPY ENV/PORT.STUFF***************************************************************** Port.Stuff** Contains**     WHOLE.PORT*     DEST.STUFF*     PEN.STUFF*     TEXT.STUFF*     OTHER.STUFF************************************************************************************************************************************* WholePortPart**        OpenPort	    mod 2 May 86*        InitPort	    mod 2 May 86*        ClosePort*        GetPort*        SetPort	    mod 2 May 86** Modification History** 7 Apr 86**    Calls now return errors of other tool calls correctly.** 2 May 86**    OpenPort, InitPort and SetPort do not size the text buffer*    for user.  This is nolong automatic and can only change*    after call by user.** 25 Aug 86**    GetPort now always returns 4 good bytes of info instead*    of just 3*********************************************************************************************************************************** DEST.STUFF** The routines in this file manipulate the destination info* in the GrafPort including the LocInfo, the PortRect, the * ClipRgn and the VisRgn.**        SetPortLoc*        GetPortLoc		new (2/6/86)*        SetPortRect	new (2/6/86)*		mod (3/11/86)*        GetPortRect	new (2/6/86)*		mod (3/11/86)*        SetPortSize*        MovePortTo*        SetOrigin		mod (3/13/86)*		mod (3/26/86)*        SetClip*        GetClip*        SetClipToRect*** Modification History Notes:** April 7, 1986**    All calls now jump through the right end call routine if*    they started by calling QDCheckActive.**    Calls that make other tool calls (setorigin, setclip, etc.)*    now return errors to these calls when they occur.*********************************************************************************************************************************** PEN.STUFF** This file contains the routines which	manipulate the pen* information in the grafport**        HidePen*        ShowPen		changed 31 mar 86*        GetPen*        GetPenState*        SetPenState*        PenMode*        GetPenMode		new (2/6/86)*        PenPat*        GetPenPat		new (2/6/86)*        SolidPenPat	new (2/6/86)*        BackPat*        GetBackPat		new (2/6/86)*		mod (7 Apr 86)*        SolidBackPat	new (2/6/86)*        SolidPattern	new (2/6/86)*        MakeSolid		new (2/6/86)*		modified (3/14/86)*        ExtendColorWord	new (3/14/86)*        SetDrawMask	new (2/28/86)*        GetDrawMask	new (2/28/86)*        PenSize*        GetPenSize		new (2/6/86)*        PenNormal*        MoveTo*        Move** Modification History Notes:** April 7, 1986**    GetBackPat was	not checking for QD	to be active nor*    returning through BusyEC4.*********************************************************************************************************************************** TEXT.STUFF** This file contains the routines which	manipulate the text* information in the GrafPort.**        SetFont		mod (7 Apr 86)*        GetFont		new (2/6/86)*        SetFontID		new (5/2/86)*        GetFontID		new (5/2/86)*        SetFontFlags	new (3/1/86)*        GetFontFlags	new (3/1/86)*        SetTextSize	new (5/2/86),mod (5/6/86)*        GetTextSize	new (5/2/86),mod (5/6/86)*        TextFace*        GetTextFace	new (2/6/86)*        TextMode*        GetTextMode	new (2/6/86)*        SpaceExtra		mod (4/25/86)*        GetSpaceExtra	new (2/6/86), mod (4/25/86)*        SetCharExtra	new (5/2/86)*        GetCharExtra	new (5/2/86)*        SetForeColor*        GetForeColor*        SetBackColor*        GetBackColor** Modification History Notes:** April 7, 1986**   SetFont now returns the same error as SizeTextBuffer.** May 2, 1986**     Added calls Get/Set CharExtra, Get/Set TextSize, Get/Set*     FontID.  Modified the SetFont call to zero the new FontID*     field in the graf port.  This allows FontID to be used*     correctly by a FontManager.************************************************************************************************************************************ OTHER.STUFF** This file contains the routines which	the user field in the* grafport.**        SetPicSave		new (2/7/86)*        GetPicSave		new (2/7/86)*        SetRgnSave		new (2/7/86)*        GetRgnSave		new (2/7/86)*        SetPolySave	new (2/7/86)*        GetPolySave	new (2/7/86)*        SetGrafProcs	new (2/7/86)*        GetGrafProcs	new (2/7/86)*        SetUserField	new (2/7/86)*        GetUserField	new (2/7/86)*        SetSysField	new (2/7/86)*        GetSysField	new (2/7/86)*        SetArcRot		moved from round 21	aug 86*        GetArcRot		moved from round 21	aug 86*********************************************************************************************************************************** OpenPort** Allocates a clip rgn and vis rgn then	calls init port.** Modification History** 2 May 86**    Does not size text buffer for user.*****************************************************************	EXPORT OpenPortOpenPort	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortPtr	equ RTL2+3	jsr QDStart	lda PortPtr,s	sta PortRef	lda PortPtr+2,s	sta PortRef+2	pea 0	; make room for result	pea 0	_NewRgn	bcs error	pea 0	pea 0	_NewRgn	bcs error	ldy #o_cliprgn	pla	sta [PortRef],y	iny	iny	pla	sta [PortRef],y	ldy #o_visrgn	pla	sta [PortRef],y	iny	iny	pla	sta [PortRef],y	bra InitThePorterror	tax	jmp BusyErr4	ENDP****************************************************************** InitPort   (PortPtr: Ptr);** Copies the standard Port to the the user's port and makes* that the current port.** Modification History** 2 May 86**    Does not size text buffer for user.** 3/7/89	Mensch* Now this routine dirties the pattern flags...****************************************************************	EXPORT InitPortInitPort	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortPtr	equ RTL2+3	jsr QDStart	lda PortPtr,s	sta PortRef	lda PortPtr+2,s	sta PortRef+2	EXPORT InitThePortInitThePort		;       	DirtyPort		ldy #PortSize-2Loop	tyx	lda >StandardPort,x	sta [PortRef],y	dey	dey	cpy #o_BkPat	bpl Loop	bit MasterSCB-1	bpl Do320	ldy #LocSize+8-2Loop2	tyx	lda >Port640,x	sta [PortRef],y	dey	dey	bpl Loop2	bra FinishItDo320	ldy #LocSize+8-2Loop3	tyx	lda >Port320,x	sta [PortRef],y	dey	dey	bpl Loop3FinishIt		;;; EXP place code here that will modify the grafport to point to shadowed RAM if that was; enabled!;	brk 00	ldy #3	; get the offset to the proper place	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne ShadowOff	; if zero, then shadowing is on	lda #$0120	; 	sta [portRef],y	; and change the port referenceShadowOff;; EXP End	PushLong #WideOpen	; set the clip region to wide open	ldy #o_cliprgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	_CopyRgn	bcs error	ldy #o_VisRgn+2	; set the vis region to bounds rect	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	lda PortRef	clc	adc #o_BoundsRect	pei PortRef+2	pha	_RectRgn	bcs error	ldx #256	; put the current system font into	ldy #o_Font	; the port	lda SysFont,x	sta [PortRef],y	iny	iny	lda SysFont+2,x	sta [PortRef],y	jmp BusyEC4error	tax	jmp BusyErr4	ENDP****************************************************************** ClosePort (Port)** Deallocates the clip and vis regions in port.*****************************************************************	EXPORT ClosePortClosePort	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortPtr	equ RTL2+3	phd	tsc	tcd	ldy #o_ClipRgn+2	jsr DisposeIt	bcs error	ldy #o_VisRgn+2	jsr DisposeIt	bcs error	jmp EndCall4error	tax	jmp ErrOut4DisposeIt		; 	lda [PortPtr],y	pha	dey	dey	lda [PortPtr],y	pha	_DisposeRgn	rts	ENDP****************************************************************** SetPort (PortPtr : ptr);** Modification History** 2 May 86**    Does not size text buffer for user	and cannot return*    error.** 3/7/89	Mensch* This routine now dirties the patterns****************************************************************	EXPORT SetPortSetPort	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortPtr	equ RTL2+3	jsr QDStart	DirtyPort	; DEBUG HERE; STore the callers return address  and the port pointer to the ROM; so the logic analyzer can pick it up...;	lda rtl2,s;	sta >$FE1230;	lda rtl2+2,s;	and #$00FF;	sta >$FE1232		lda PortPtr,s	sta PortRef	lda PortPtr+1,s	sta PortRef+1		jmp BusyEC4	ENDP****************************************************************** GetPort    : Ptr** Change History** August 25, 1986	   SEG**    This now makes	sure highest byte of pointer is zero.*****************************************************************	EXPORT GetPortGetPort	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortPtr	equ RTL2+3	jsr QDStart	lda PortRef	; first put pointer	to port	sta PortPtr,s	; in user's variable	lda PortRef+2	and #$00FF	; mask off system window flag	sta PortPtr+2,s	jmp BusyEC0	ENDP****************************************************************** SetPortLoc   (LocPtr : Ptr);** 3/7/89	Mensch* This routine changes bounds rects so.. dirty the patterns****************************************************************	EXPORT SetPortLocSetPortLoc	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3LocPtr	equ RTL2+3	jsr QDStart	DirtyPort		lda LocPtr,s	sta Temp	lda LocPtr+1,s	sta Temp+1	ldy #LocSize-2Loop	lda [Temp],y	sta [PortRef],y	dey	dey	bpl Loop	jmp BusyEC4	ENDP****************************************************************** GetPortLoc   (LocPtr : Ptr);*****************************************************************	EXPORT GetPortLocGetPortLoc	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3LocPtr	equ RTL2+3	jsr QDStart	lda LocPtr,s	sta Temp	lda LocPtr+1,s	sta Temp+1;--------------------------------------------;; This is extra simple because the loc info; is at the beginning of the port.;	ldy #LocSize-2Loop	lda [PortRef],y	sta [Temp],y	dey	dey	bpl Loop	jmp BusyEC4	ENDP****************************************************************** SetPortRect   (RectPtr : long);** Sets the port rectangle to the rect that is passed.** Fixed Bug 11-Mar-86 SEG** 3/7/89	Mensch* This thing might change the way we shift... so Bad patterns****************************************************************	EXPORT SetPortRectSetPortRect	PROCOrigBank	equ 1OrigDirect	equ OrigBank+1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RectPtr	equ RTL2+3	jsr QDStart	DirtyPort		phb	; save bank	lda RectPtr,s	; get pos in bank into x	tax	lda RectPtr+1,s	; put high 2 bytes on stack	pha	plb	; pull of middle byte	plb	; now pull off high	byte so*		; x is offset in bank to rect	ldy #o_portrectLoop	lda |0,x	sta [PortRef],y	inx	inx	iny	iny	cpy #o_PortRect+8	bcc Loop	plb	; restore bank	jmp BusyEC4	ENDP****************************************************************** GetPortRect   (RectPtr : long);** Copies the port rectangle to the rect	that is passed.** Fixed Bug 11-Mar-86 SEG*****************************************************************	EXPORT GetPortRectGetPortRect	PROCOrigBank	equ 1OrigDirect	equ OrigBank+1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RectPtr	equ RTL2+3	jsr QDStart	phb	; save bank	lda RectPtr,s	; get pos in bank into x	tax	lda RectPtr+1,s	; put high 2 bytes on stack	pha	plb	; pull of middle byte	plb	; now pull off high	byte so*		; x is offset in bank to rect	ldy #o_portrectLoop	lda [PortRef],y	sta |0,x	inx	inx	iny	iny	cpy #o_PortRect+8	bcc Loop	plb	; restore bank	jmp BusyEC4	ENDP****************************************************************** SetPortSize   (PortWidth, PortHeight : integer);*****************************************************************	EXPORT SetPortSizeSetPortSize	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortHeight	equ RTL2+3PortWidth	equ PortHeight+2	jsr QDStart	DirtyPort		jsl PortLoc2ZP	lda PortHeight,s	clc	adc PortRect	sta PortRect+4	lda PortWidth,s	clc	adc PortRect+2	sta PortRect+6	jsl ZP2PortLoc	jmp BusyEC4	ENDP****************************************** MovePortTo  (H,V : integer);** 3/7/89	Mensch* Canchange the bnounds rect so... dirty patterns****************************************	EXPORT MovePortToMovePortTo	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortY	equ RTL2+3PortX	equ PortY+2	jsr QDStart	DirtyPort		jsl PortLoc2ZP	lda PortRect+4	sec	sbc PortRect	clc	adc PortY,s	sta PortRect+4	lda PortY,s	sta PortRect	lda PortRect+6	sec	sbc PortRect+2	clc	adc PortX,s	sta PortRect+6	lda PortX,s	sta PortRect+2	jsl ZP2PortLoc	jmp BusyEC4	ENDP****************************************************************** SetOrigin    (H,V	: integer);** Offsets the PortRect and BoundsRect so that the port rect	has* value passed and their positions remain the same relative	to* each other.** Modified 13-Mar-86 by SEG**    I was reading the inputs backwards	so I fixed the equates.** Modified 26 Mar 86 by SEG**    Offset region is available so I offset the VisRgn.** 3/7/89	Mensch* Patterns are dirty/ bounds rect changed...****************************************************************	EXPORT SetOriginSetOrigin	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PortY	equ RTL2+3PortX	equ PortY+2	jsr QDStart	DirtyPort		jsl PortLoc2ZP	lda PortY,s	; Start by caculating DeltaY	sec	sbc PortRect	tay	; Now offset rects by DeltaY	clc	; This same code in	a loop	adc BoundsRect	; is as many instructions	sta BoundsRect	; and runs slower so	tya	; I do it in line.	clc	adc BoundsRect+4	sta BoundsRect+4	tya	clc	adc PortRect	sta PortRect	tya	clc	adc PortRect+4	sta PortRect+4	tyx	; save deltay in x	lda PortX,s	; Now Calculate DeltaX	sec	sbc PortRect+2	tay	; offset rects by DeltaX	clc	; This same code in	a loop	adc BoundsRect+2	; is as many instructions	sta BoundsRect+2	; and runs slower so	tya	; I do it in line.	clc	adc BoundsRect+6	sta BoundsRect+6	tya	clc	adc PortRect+2	sta PortRect+2	tya	clc	adc PortRect+6	sta PortRect+6	pea 0	; put long word on stack	pea 0	phy	; push delta x	phx	; push delta y	ldy #o_VisRgn	; replace long word	on stack with	lda [PortRef],y	; handle to vis rgn	sta 5,s	iny	iny	lda [PortRef],y	sta 7,s	_OffsetRgn	; and offset region	bcs error	jsl ZP2PortLoc	jmp BusyEC4error	tax	jmp BusyErr4	ENDP****************************************************************** SetClip      (RgnHandle : handle)*****************************************************************	EXPORT SetClipSetClip	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RgnHandle	equ RTL2+3	jsr QDStart	lda RgnHandle,s	tax	lda RgnHandle+2,s	pha	phx	ldy #o_ClipRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	_CopyRgn	tax	jmp BusyErr4	ENDP****************************************************************** GetClip*****************************************************************	EXPORT GetClipGetClip	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RgnHandle	equ RTL2+3	jsr QDStart	ldy #o_ClipRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	lda RgnHandle+4,s	; plus 4 because of	4 new bytes on stack	tax	lda RgnHandle+2+4,s	pha	phx	_CopyRgn	tax	jmp BusyErr4	ENDP****************************************************************** SetClipToRect*****************************************************************	EXPORT SetClipToRectSetClipToRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RectPtr	equ RTL2+3	jsr QDStart	ldy #o_ClipRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	lda RectPtr+4,s	; +4 because of 4 new bytes on stack	tax	lda RectPtr+2+4,s	pha	phx	_RectRgn	tax	jmp BusyErr4	ENDP****************************************************************** SetVisRgn    (RgnHandle : handle)*****************************************************************	EXPORT SetVisRgnSetVisRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RgnHandle	equ RTL2+3	jsr QDStart	lda RgnHandle,s	tax	lda RgnHandle+2,s	pha	phx	ldy #o_VisRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	_CopyRgn	tax	jmp BusyErr4	ENDP****************************************************************** GetVisRgn*****************************************************************	EXPORT GetVisRgnGetVisRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RgnHandle	equ RTL2+3	jsr QDStart	ldy #o_VisRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	lda RgnHandle+4,s	; plus 4 because of	4 new bytes on stack	tax	lda RgnHandle+2+4,s	pha	phx	_CopyRgn	tax	jmp BusyErr4	ENDP****************************************************************** HidePen*****************************************************************	EXPORT HidePenHidePen	PROC	jsr QDStart	ldy #O_PnVis	lda [PortRef],y	dec a	sta [PortRef],y	bpl @HPDone	; if this flag is non-negative, pen visible	DirtyDrawState	; else mark the drawstate as dirty...@HPDone	jmp BusyEC0	ENDP****************************************************************** ShowPen*****************************************************************	EXPORT ShowPenShowPen	PROC	jsr QDStart	ldy #O_PnVis	lda [PortRef],y	inc a	sta [PortRef],y		jmp BusyEC0	ENDP****************************************************************** GetPen     PtPtr : Ptr*****************************************************************	EXPORT GetPenGetPen	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PtPtr	equ RTL2+3	jsr QDStart	lda PtPtr,s	sta Temp	lda PtPtr+1,s	sta Temp+1	ldy #O_PnLoc	lda [PortRef],y	sta [Temp]	iny	iny	lda [PortRef],y	ldy #2	sta [Temp],y	jmp BusyEC4	ENDP****************************************************************** GetPenState  (PenState : Ptr);*****************************************************************	EXPORT GetPenStateGetPenState	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PenStatePtr	equ RTL2+3	jsr QDStart	lda PenStatePtr,s	tax	lda PenStatePtr+1,s	phb	; save the bank register	pha	; put this on the stack	plb	; set b twice	plb	; second value is valid	ldy #O_PnLocLoop	lda [PortRef],y	sta |0,x	inx	inx	iny	iny	cpy #O_PnLoc+PnStateSize	bcc Loop	plb	; restore bank	jmp BusyEC4	ENDP****************************************************************** SetPenState  (PenStatePtr : ptr)*****************************************************************	EXPORT SetPenStateSetPenState	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PenStatePtr	equ RTL2+3	jsr QDStart	DirtyPort		lda PenStatePtr,s	tax	lda PenStatePtr+1,s	phb	; save the bank register	pha	; put this on the stack	plb	; set b twice	plb	; second value is valid	ldy #O_PnLocLoop	lda |0,x	sta [PortRef],y	inx	inx	iny	iny	cpy #O_PnLoc+PnStateSize	bcc Loop	plb	; restore bank	jmp BusyEC4	ENDP****************************************************************** PenPat    (PatPtr	: Ptr);*****************************************************************	EXPORT PenPatPenPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart		jsl UserPat2ZP	jsl ZP2Pen	jmp BusyEC4	; all done.	ENDP****************************************************************** GetPenPat    (PatPtr : Ptr);*****************************************************************	EXPORT GetPenPatGetPenPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart	jsl Pen2ZP	jsl ZP2UserPat	jmp BusyEC4	; all done.	ENDP****************************************************************** SolidPenPat	(Color : integer)*****************************************************************	EXPORT SolidPenPatSolidPenPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Color	equ RTL2+3	jsr QDStart	lda Color,s	tax	lda [PortRef]	jsr MakeSolid	jsl ZP2Pen	jmp BusyEC2	; all done.	ENDP****************************************************************** SetDrawMask    (MaskPtr : Ptr);*****************************************************************	EXPORT SetDrawMaskSetDrawMask	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart	DirtyMask		jsl UserMask2ZP	jsl ZP2Mask	jmp BusyEC4	; all done.	ENDP****************************************************************** GetDrawMask   (MaskPtr : Ptr);*****************************************************************	EXPORT GetDrawMaskGetDrawMask	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart	jsl Mask2ZP	jsl ZP2UserMask	jmp BusyEC4	; all done.	ENDP****************************************************************** BackPat    (PatPtr : Ptr);*****************************************************************	EXPORT BackPatBackPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart	jsl UserPat2ZP	jsl ZP2Back	jmp BusyEC4	; all done.	ENDP****************************************************************** GetBackPat    (PatPtr : Ptr);** Modified April 7,	1986**    Was not checking for QD to be active nor*    returning through BusyEC4.*****************************************************************	EXPORT GetBackPatGetBackPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	jsr QDStart	jsl Back2ZP	jsl ZP2UserPat	jmp BusyEC4	; all done.	ENDP****************************************************************** SolidBackPat	 (Color : integer)*****************************************************************	EXPORT SolidBackPatSolidBackPat	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Color	equ RTL2+3	jsr QDStart	lda Color,s	tax	lda [PortRef]	jsr MakeSolid	jsl ZP2Back	jmp BusyEC2	; all done.	ENDP****************************************************************** SolidPattern	      (Color : integer; PatPtr : long)*****************************************************************	EXPORT SolidPatternSolidPattern	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3Color	equ PatPtr+4	jsr QDStart	lda Color,s	tax	lda MasterSCB	jsr MakeSolid	jsl ZP2UserPat	jmp BusyEC6	; all done.	ENDP****************************************************************** MakeSolid** Makes FillPat a solid color.  The color is passed in x-reg* and the SCB word is passed in a-reg.** 3/7/89	Mensch* Of course, this changes the pattern so...Dirty pattern****************************************************************	EXPORT MakeSolidMakeSolid	PROC	pha	phx	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #AllPatsBad	; turn off both patterns	sta <DirtyDPFlags,x	plx	pla	jsr ExtendColorWordStuffIt	ldx #256Loop	sta TheFillPat,x	inx	inx	cpx #PatSize+256	bcc Loop	rts	ENDP****************************************************************** ExtendColorWord** Takes the low two	or four bits in the	x register and extends* them into the rest of a word passed back in the a register.** Decides whether to use a 2 or 4 bit source based on word in* a register (either the port or Master	SCB).*****************************************************************	EXPORT ExtendColorWordExtendColorWord	PROC	and #$0080	beq Mode320	txa	and #$0003SafeColor	asl a	tax	lda >Colors640,x	rtsMode320	txa	and #$000F	asl a	tax	lda >Colors320,x	rtsColors640		; 	DC.W %0000000000000000	DC.W %0101010101010101	DC.W %1010101010101010	DC.W %1111111111111111Colors320		; 	DC.W $0000,$1111,$2222,$3333	DC.W $4444,$5555,$6666,$7777	DC.W $8888,$9999,$AAAA,$BBBB	DC.W $CCCC,$DDDD,$EEEE,$FFFF	ENDP****************************************************************** PenSize (width, height : integer);*****************************************************************	EXPORT PenSizePenSize	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheHeight	equ RTL2+3TheWidth	equ TheHeight+2	jsr QDStart	lda TheHeight,s	ldy #O_PnSize	sta [PortRef],y	lda TheWidth,s	iny	iny	sta [PortRef],y	jmp BusyEC4	ENDP****************************************************************** GetPenSize   SizePtr : Ptr*****************************************************************	EXPORT GetPenSizeGetPenSize	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3SizePtr	equ RTL2+3	jsr QDStart	lda SizePtr,s	sta Temp	lda SizePtr+1,s	sta Temp+1	ldy #O_PnSize	lda [PortRef],y	sta [Temp]	iny	iny	lda [PortRef],y	ldy #2	sta [Temp],y	jmp BusyEC4	ENDP****************************************************************** PenNormal** Does not move the	pen location.** 3/7/89	Mensch* This can change patterns so... Dirty patterns****************************************************************	EXPORT PenNormalPenNormal	PROC	jsr QDStart	DirtyPort		ldx #0	ldy #O_PnLoc+4Loop	lda >StdPnState+4,x	sta [PortRef],y	inx	inx	iny	iny	cpy #O_PnLoc+PnStateSize	bcc Loop	jmp BusyEC0	ENDP****************************************************************** MoveTo (h,v : integer);*****************************************************************	EXPORT MoveToMoveTo	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3V	equ RTL2+3H	equ V+2	jsr QDStart	lda V,s	ldy #O_PnLoc	sta [PortRef],y	lda H,s	iny	iny	sta [PortRef],y	jmp BusyEC4	ENDP****************************************************************** Move   (dh,dv : integer);*****************************************************************	EXPORT MoveMove	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3dV	equ RTL2+3dH	equ dV+2	jsr QDStart	lda dv,s	ldy #O_PnLoc	clc	adc [PortRef],y	sta [PortRef],y	lda dh,s	iny	iny	clc	adc [PortRef],y	sta [PortRef],y	jmp BusyEC4	ENDP****************************************************************** SetFont (H : handle)*** Modifications**    April 7, 1986	  SetFont now returns the value returned*	  by SizeTextBuffer	as the error code.**    May 2, 1986	  SetFont does not call SizeTextBuffer.*	  SetFont does zero	the new FontID field*	  so that fontmanager can know it has*	  been bypassed.*****************************************************************	EXPORT SetFontSetFont	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Handle	equ RTL2+3	jsr QDStart;; First test to see if the handle passed is the ROMFont; if it is, then we will test to see if we should load the fast font;	lda Handle,s	; get the low word...	cmp #SystemFont	; see if its the ROM font	bne @StdFont	lda Handle+2,s	cmp #^SystemFont;; The following is gone now in an attempt to hide the fastfont!; 3/21/89	mensch;;	beq @ROMFont@StdFont; If we get here, the handle passed was not the ROM font...; so just set it as the new font.	lda Handle,s	; get low word of handle	ldy #o_Font	; get offset in grafport	sta [PortRef],y	; store low word into grafport	lda Handle+2,s	; get high word of handle	iny	; bump y by 2	iny	sta [PortRef],y	; store high word into grafport@Continue	ldy #o_FontID	; zero the FontID field in	lda #0	; graf port	sta [PortRef],y	iny	iny	sta [PortRef],y	jmp BusyEC4	; all done@ROMFont; We get to this routine if the user tries to set the ROM font as the ; current font. It will substitute the value in our direct page; for the ROM font number	ldx #512	lda FastRomFont,x	ora FastRomFont+2,x	beq @StdFont	; if these locations are zero, no fast font		ldy #o_Font	lda FastRomFont,x	sta [portRef],y	ldy #o_Font+2	lda FastRomFont+2,x	sta [portRef],y	bra @Continue	ENDP******************************************************************************************************************************************************************************************************			  ******	 The Set port word routines	  ******			  ******************************************************************************************************************************************************************************************************	EXPORT PortWordsPortWords	PROC	EXPORT PenModePenMode		;       	ldy #O_PnMode	bra PortWord	EXPORT SetTextSizeSetTextSize		;       	ldy #O_TxSize	bra PortWord	EXPORT SetFontFlagsSetFontFlags		;       	ldy #O_FontFlags	bra PortWord	EXPORT TextFaceTextFace		;       	ldy #O_TxFace	bra PortWord	EXPORT TextModeTextMode		;       	ldy #O_TxMode	bra PortWord	EXPORT SetForeColorSetForeColor		;       	ldy #O_FGColor	bra PortWord	EXPORT SetBackColorSetBackColor		;       	ldy #O_BGColor	bra PortWord	EXPORT SetArcRotSetArcRot		;       	ldy #o_ArcRot;               bra	PortWord	; let this last one	fall in****************************************************************** PortWord** Takes word input off the stack (6 bytes deep) and puts it* into the port at the offset in Y.** This is the work horse of the port call routines.*****************************************************************PortWord		; OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheValue	equ RTL2+3	jsr QDStart	lda TheValue,s	; get value off stack	sta [PortRef],y	; store into current port	jmp BusyEC2	; Clean stack and quit	ENDP******************************************************************************************************************************************************************************************************			  ******              The Set port long routines	  ******			  *************************************************************************************************************************************** Change History** March 89	Mensch** Break SetGrafProcs trying to dirty the flags on page 3.* Tried to do it before direct page was switched in.** March 17, 1989	Steven Glass** Fix SetGrafProcs.  Startup QD first.******************************************************************	EXPORT PortLongsPortLongs	PROC	EXPORT SpaceExtraSpaceExtra		;       	ldy #O_SpExtra	bra PortLong	EXPORT SetCharExtraSetCharExtra		;       	ldy #O_ChExtra	bra PortLong	EXPORT SetPicSaveSetPicSave		;       	ldy #O_PicSave	bra PortLong	EXPORT SetRgnSaveSetRgnSave		;       	ldy #O_RgnSave	bra PortLong	EXPORT SetPolySaveSetPolySave		;       	ldy #O_PolySave	bra PortLong	EXPORT SetGrafProcsSetGrafProcs	jsr QDStart	DirtyDrawState	; set a bad drawing state	ldy #O_GrafProcs	bra PortLong2	EXPORT SetUserFieldSetUserField		;       	ldy #O_UserField	bra PortLong	EXPORT SetSysFieldSetSysField		;       	ldy #O_SysField	bra PortLong	EXPORT SetClipHandleSetClipHandle		;       	ldy #O_ClipRgn	bra PortLong	EXPORT SetVisHandleSetVisHandle		;       	ldy #O_VisRgn	bra PortLong	EXPORT SetFontIDSetFontID		;       	ldy #O_FontID;               bra	PortLong	; let this last one	fall in****************************************************************** PortLong** Takes long input off the stack (6 bytes deep) and puts it* into the port at the offset in Y.*****************************************************************PortLong		; OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheLong	equ RTL2+3	jsr QDStartPortLong2	lda TheLong,s	sta [PortRef],y	lda TheLong+2,s	iny	iny	sta [PortRef],y	jmp BusyEC4	ENDP******************************************************************************************************************************************************************************************************			  ******              The Get Word from Port	Routines	  ******			  ******************************************************************************************************************************************************************************************************	EXPORT GetPortWordsGetPortWords	PROC	EXPORT GetPenModeGetPenMode		;       	ldy #O_PnMode	bra GetPortWord	EXPORT GetTextSizeGetTextSize		;       	ldy #O_TxSize	bra GetPortWord	EXPORT GetFontFlagsGetFontFlags		;       	ldy #O_FontFlags	bra GetPortWord	EXPORT GetTextFaceGetTextFace		;       	ldy #O_TxFace	bra GetPortWord	EXPORT GetTextModeGetTextMode		;       	ldy #O_TxMode	bra GetPortWord	EXPORT GetForeColorGetForeColor		;       	ldy #O_FGColor	bra GetPortWord	EXPORT GetBackColorGetBackColor		;       	ldy #O_BGColor	bra GetPortWord	EXPORT GetArcRotGetArcRot		;       	ldy #o_ArcRot;                bra GetPortWord	; let this last one	fall in****************************************************************** GetPortWord** Takes word from port (offset in Y) and puts it on the* stack (6 bytes deep).** Routines that return word values from	the port will* unconditionally transfer control here.*****************************************************************GetPortWord		; OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheValue	equ RTL2+3	jsr QDStart	lda [PortRef],y	; get the word	sta TheValue,s	; put it on the stack	jmp BusyEC0	ENDP******************************************************************************************************************************************************************************************************			  ******              The Get long from Port	Routines	  ******			  ******************************************************************************************************************************************************************************************************	EXPORT GetPortLongsGetPortLongs	PROC	EXPORT GetFontGetFont		;       	ldy #O_Font	bra GetPortLong	EXPORT GetFontIDGetFontID		;       	ldy #O_FontID	bra GetPortLong	EXPORT GetSpaceExtraGetSpaceExtra		;       	ldy #O_SpExtra	bra GetPortLong	EXPORT GetCharExtraGetCharExtra		;       	ldy #O_ChExtra	bra GetPortLong	EXPORT GetPicSaveGetPicSave		;       	ldy #O_PicSave	bra GetPortLong	EXPORT GetRgnSaveGetRgnSave		;       	ldy #O_RgnSave	bra GetPortLong	EXPORT GetPolySaveGetPolySave		;       	ldy #O_PolySave	bra GetPortLong	EXPORT GetGrafProcsGetGrafProcs		;       	ldy #O_GrafProcs	bra GetPortLong	EXPORT GetUserFieldGetUserField		;       	ldy #O_UserField	bra GetPortLong	EXPORT GetSysFieldGetSysField		;       	ldy #O_SysField	bra GetPortLong	EXPORT GetClipHandleGetClipHandle		;       	ldy #O_ClipRgn	bra GetPortLong	EXPORT GetVisHandleGetVisHandle		;       	ldy #O_VisRgn;               bra	GetPortLong	; let this last one	fall in****************************************************************** GetPortLong** Takes long from grafport (at offset y) and puts it on the* stack (6 bytes deep).** Modifications**      April 10, 1986    This was copied from SetPortLong*	     and I patched it wrong so it only*	     returned the high word of the long.*****************************************************************GetPortLong		; OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheLong	equ RTL2+3	jsr QDStart	lda [PortRef],y	sta TheLong,s	iny	iny	lda [PortRef],y	sta TheLong+2,s	jmp BusyEC0	ENDP;                COPY ENV/PORT.UTILS****************************************************************** PORT.UTILS** This file contains routines that are handy for putting things* into and getting things out of a port.**        PortLoc2ZP	      Copies location info from port to	ZP*        ZP2PortLoc	      Copies location info from ZP to port*        UserPat2ZP	      Copies pattern from user memory to*	      zero page*        ZP2UserPat	      Copies pattern from zero page to user*	      memory.*        GetPenPReady     Copies the penpat from the port to ZP*	      and aligns it	to the bounds rect.*        GetBackPReady    Copies the backpat from the port to*	      ZP and aligns	it to the bounds rect.*        Pen2ZP	      Copies the pen pattern to zero page*	      without alignment.*        Back2ZP	      Copies the back pattern to zero page.*	      without alignment.*        ZP2Pen	      Copies the pattern on zp to pen pat in*	      grafport.*        ZP2Back	      Copies the pattern on zp to back pat*	      in grafport.*        RotatePat	      Rotates the pattern in TheFillPat	an*	      amount passed	in the Y-reg.****        GetMaskReady     Calls Mask2ZP, ExpandMask and RotateMask*	      to get the mask ready for drawing.*        UserMask2ZP      Copies the user's mask to TheDrawMask*	      on zero page*        ZP2UserMask      Copies TheDrawMask on zero page to*	      the user's memory.*        Mask2ZP	      Copies the pen mask from the GrafPort*	      to zero page.*        ZP2Mask	      Copies the pen mask from ZP to the*	      GrafPort*        ExpandMask	      Expands the penmask on zero page in place**        RotateMask	      Rotates the mask in place a number of*	      pixels passed	in the a-reg.*        RotateLong	      Used by RotateMask to do rotating.*********************************************************************************************************************************** PortLoc2ZP** This is the routine that copies the port info from the port* down to zero page** 2/25/89	Mensch* Make this one straight down ladder to save some cycles!** Saves 90 cycles over the old way...*****************************************************************	EXPORT iPortLoc2ZPiPortLoc2ZP	PROC		phb	; save the current databank	pei PortRef+1	; switch to the grafports databank	plb	plb		ldy <PortRef	; now set Y as an index into our data area	lda |0,y	sta <LocInfo+0	lda |2,y	sta <LocInfo+2	lda |4,y	sta <LocInfo+4	lda |6,y	sta <LocInfo+6	lda |8,y	sta <LocInfo+8	lda |10,y	sta <LocInfo+10	lda |12,y	sta <LocInfo+12	lda |14,y	sta <LocInfo+14	lda |16,y	sta <LocInfo+16	lda |18,y	sta <LocInfo+18	lda |20,y	sta <LocInfo+20	lda |22,y	sta <LocInfo+22	plb		phx	; <X> register	ldx #512	; and set the DirtyDP Flags...	lda <DirtyDPFlags,x	ora #PortLocOK	sta <DirtyDPFlags,x	plx	rtl;	ldy #LocSize+8-2;Loop	tyx;	lda [PortRef],y;	sta LocInfo,x;	dey;	dey;	bpl Loop;;	rtl	ENDP****************************************************************** ZP2PortLoc** This is the routine that copies the port info on zero page* up to the graf port after it is modified.*****************************************************************	EXPORT ZP2PortLocZP2PortLoc	PROC	ldy #LocSize+8-2Loop	tyx	lda LocInfo,x	sta [PortRef],y	dey	dey	bpl Loop	rtl	ENDP****************************************************************** UserPat2ZP** Copies the pattern pointed to by value on stack to zero page.* The pointer is several bytes deep on the stack but we're* clever enough to read it anyway.** Trashes all registers and the zero page location TEMP.** 3/7/89	Mensch* again, this also dirties the patterns so change the flags...****************************************************************	EXPORT iUserPat2ZPiUserPat2ZP	PROCRTLAdr	equ 1OrigDirect	equ RTLAdr+3RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	DirtyPatterns		lda PatPtr,s	; put low word of ptr in x	sta Temp	lda PatPtr+1,s	; get med and high bytes	sta Temp+1;-----------------------------------------------;; Since TheFillPat is on the next page,	I access; it with ZP,x addressing with x initially set; to 256.;	ldy #0	ldx #256Loop	lda [Temp],y	sta TheFillPat,x	inx	inx	iny	iny	cpy #PatSize	bcc Loop	rtl	ENDP****************************************************************** ZP2UserPat** Copies the pattern on zero page to the area of memory pointed* to by value on stack.  the pointer is	several bytes deep on* the stack but we're clever enough to read it anyway.** Trashes all registers and the zero page location TEMP.*****************************************************************	EXPORT ZP2UserPatZP2UserPat	PROCRTLAdr	equ 1OrigDirect	equ RTLAdr+3RTL1	equ OrigDirect+2RTL2	equ RTL1+3PatPtr	equ RTL2+3	lda PatPtr,s	; put low word of ptr in x	sta Temp	lda PatPtr+1,s	; get med and high bytes	sta Temp+1;-----------------------------------------------;; Since TheFillPat is on the next page,	I access; it with ZP,x addressing with x initially set; to 256.;	ldy #0	ldx #256loop	lda TheFillPat,x	sta [Temp],y	inx	inx	iny	iny	cpy #PatSize	bcc Loop	rtl	ENDP****************************************************************** Utility routines for moving patterns around.  They move* patterns from the	port to zero page, from zero page to the* port, from the user to zero page and from zero page to the* user.*********************************************************************************************************************************** GetPenPReady** Moves PenPat to the TheFillPat on zero page and rotates the* pattern for alignment with the BoundsRect.** 3/7/89	Mensch* Modified to support the new dirtyflags** 4/22/89	Mensch* Modified to support arcrot field for 16 pixel patterns in 640 mode****************************************************************	EXPORT iGetPenPReadyiGetPenPReady	PROC		ldx #512	; swap direct	lda <DirtyDPFlags,x	; load the proper flags	bpl @GottaGoSlow	tay	; save this for a sec...	and #PenPatOK	; test the penPatFlag	bne @PenAlreadyUp	tya	; get flags back...	ora #PenPatOK	and #BackPatternBad ; turn off the back pattern flags	sta <DirtyDPFlags,x	; and resave this thing...@GottaGoSlow	jsl Pen2ZP	; bring the pen pattern to zp;; Mensch 4/22/89; This code was written before arcrot could allow 16 pixel patterns.; This will now fix 16 pixel patterns up also...	ldy #o_ArcRot	; look at high bit of ArcRot	lda [PortRef],y	; test bit 15 of arcrot and	and PortSCB-1	; bit 7 of PortSCB to see if we need to use	bpl @NoFutz	; 15 pixel patterns	lda #15	bra @cont@NoFutz	lda #7@Cont	and BoundsRect+2	; rotate it	tay	; RotatePat takes param in Yreg	jsl RotatePat@PenAlreadyUp	rtl	ENDP****************************************************************** GetBackPReady** Moves BackPat to the thefillpat on zero page and rotates the* pattern for alignment with the BoundsRect.*** 3/7/89	Mensch* Modified to support the new dirtyflags** 4/22/89	Mensch* Modified to support arcrot field for 16 pixel patterns in 640 mode****************************************************************	EXPORT iGetBackPReadyiGetBackPReady	PROC	ldx #512	; swap direct	lda <DirtyDPFlags,x	; load the proper flags	bpl @GottaGoSlow	tay	; save this for a sec...	and #BackPatternOK	; test the penPatFlag	bne @BackAlreadyUp	tya	; get flags back...	ora #BackPatternOK	and #PenPatBad 	; turn off the back pattern flags	sta <DirtyDPFlags,x	; and resave this thing...@GottaGoSlow	jsl Back2ZP	; move the background pattern to zp;; Mensch 4/22/89; This code was written before arcrot could allow 16 pixel patterns.; This will now fix 16 pixel patterns up also...	ldy #o_ArcRot	; look at high bit of ArcRot	lda [PortRef],y	; test bit 15 of arcrot and	and PortSCB-1	; bit 7 of PortSCB to see if we need to use	bpl @NoFutz	; 15 pixel patterns	lda #15	bra @cont@NoFutz	lda #7@Cont	and BoundsRect+2	; rotate it	tay	; RotatePat takes param in Yreg	jsl RotatePat@BackAlreadyUp	rtl	ENDP****************************************************************** Pen2ZP** Moves the pen pattern to zero page.*****************************************************************	EXPORT iPen2ZPiPen2ZP	PROC	ldx #256	ldy #O_PnPat	lda [PortRef],y	pha	sta TheFillPat,x	bra Loop3Loop2	lda [PortRef],y	cmp 1,s	bne NotSolid	sta TheFillPat,xLoop3	iny	iny	inx	inx	cpx #PatSize+256	bcc Loop2	pla	; discard the temp...	ldx #512	lda <DirtyDPFlags,x	ora #SolidPatOK	sta <DirtyDPFlags,x	rtl	NSLoop2	lda [PortRef],yNotSolid	sta TheFillPat,x	iny	iny	inx	inx	cpx #PatSize+256	bcc NSLoop2	pla	; discard the temp...	ldx #512	lda <DirtyDPFlags,x	and #$FFFF-SolidPatOK ; solid pat bad!	sta <DirtyDPFlags,x	rtl	ENDP****************************************************************** Back2ZP** Moves the background pattern to zero page.*****************************************************************	EXPORT iBack2ZPiBack2ZP	PROC	ldx #256	ldy #O_BkPat	lda [PortRef],y	pha	sta TheFillPat,x	bra Loop3Loop2	lda [PortRef],y	cmp 1,s	bne NotSolid	sta TheFillPat,xLoop3	iny	iny	inx	inx	cpx #PatSize+256	bcc Loop2	pla	; discard the temp...	ldx #512	lda <DirtyDPFlags,x	ora #SolidPatOK	sta <DirtyDPFlags,x	rtl	NSLoop2	lda [PortRef],yNotSolid	sta TheFillPat,x	iny	iny	inx	inx	cpx #PatSize+256	bcc NSLoop2	pla	; discard the temp...	ldx #512	lda <DirtyDPFlags,x	and #$FFFF-SolidPatOK ; solid pat bad!	sta <DirtyDPFlags,x	rtl	ENDP****************************************************************** ZP2Pen** Moves pattern on zero page to pen pat	in the port.*****************************************************************	EXPORT ZP2PenZP2Pen	PROC	ldx #256	ldy #O_PnPatLoop	lda TheFillPat,x	sta [PortRef],y	iny	iny	inx	inx	cpx #PatSize+256	bcc Loop	rtl	ENDP****************************************************************** ZP2Back** Moves the pattern	on zero page to the	back pat in the* graf port.*****************************************************************	EXPORT ZP2BackZP2Back	PROC	ldx #256	ldy #O_BkPatLoop	lda TheFillPat,x	sta [PortRef],y	iny	iny	inx	inx	cpx #PatSize+256	bcc Loop	rtl	ENDP****************************************************************** RotatePat** Rotates TheDrawMask on zero page. The	amount to rotate is* passed in the y-register.*** Change History** 08 Sep 88	Steven Glass** The 640 mode pattern is expanded to use the entire 32 bytes* of the pattern.  This means that code that uses the pattern* does not have to care what mode it is in.** 02 Oct 88	Steven Glass** Check the high bit of arc rot to see if we should* copy the 16 byte pattern into 32 bytes.*****************************************************************iRotatePat	PROC EXPORT	phy	; save the y-reg	ldy #o_ArcRot	; look at high bit of ArcRot	lda [PortRef],y	bmi NoFutz	bit PortSCB-1	bpl NoFutz	phd	tdc	clc	adc #$100	tcd	lda TheFillPat+14	sta TheFillPat+28	sta TheFillPat+30	lda TheFillPat+12	sta TheFillPat+24	sta TheFillPat+26	lda TheFillPat+10	sta TheFillPat+20	sta TheFillPat+22	lda TheFillPat+8	sta TheFillPat+16	sta TheFillPat+18	lda TheFillPat+6	sta TheFillPat+12	sta TheFillPat+14	lda TheFillPat+4	sta TheFillPat+8	sta TheFillPat+10	lda TheFillPat+2	sta TheFillPat+4	sta TheFillPat+6	lda TheFillPat+0	sta TheFillPat+2	pldNoFutz	ply	tya	cmp #0	beq NeverMind	asl a	bit PortSCB-1	bmi Mode640	asl a	; bump this once more for 320 modeMode640	sta HowFarToShift	ldx #256	; use this in x since mask is 		; really on the next pageLoop	lda TheFillPat+2,x	; get the current slice	tay	lda TheFillPat,x	phx	; save x on stack	jsl RotateLong	; rotate it	plx	; get x back	sta TheFillPat,x	; put the current slice back	tya	sta TheFillPat+2,x	inx	; bump x and check to see if we	inx	; are done.	inx	inx	cpx #256+PatSize	bcc LoopNeverMind	rtl	ENDP****************************************************************** GetMaskReady** Brings the 1-bit per pixel mask down to zero page from the* grafport, expands	it, and rotates it to align it with the* bounds rect.** 3/8/89	Mensch* Support Dirty masking now...****************************************************************	EXPORT iGetMaskReadyiGetMaskReady	PROC	ldx #512	lda <DirtyDPFlags,x	bpl @MustGoSlow	tay	; save this for a sec...	and #PenMaskOK	; test to see if the mask is ok...	bne @NoNeed	tya	ora #PenMaskOK	; flag the pen mask as OK...	sta <DirtyDPFlags,x@MustGoSlow	jsl Mask2ZP	; bring the pen mask to zp	jsl ExpandMask	; expand the mask to n-bits per pixel	lda BoundsRect+2	; rotate the mask so it is aligned	and #7	; with the bounds rect!	jsl RotateMask	; note that rotatemask takes shift*		; amount in areg@NoNeed	rtl	ENDP****************************************************************** UserMask2ZP** Moves the specified mask to TheDrawMask on zero page.*****************************************************************	EXPORT UserMask2ZPUserMask2ZP	PROCRTLAdr	equ 1OrigDirect	equ RTLAdr+3RTL1	equ OrigDirect+2RTL2	equ RTL1+3MaskPtr	equ RTL2+3	lda MaskPtr,s	; put low word of ptr in x	sta Temp	lda MaskPtr+1,s	; get med and high bytes	sta Temp+1;-----------------------------------------------;; Since TheFillPat is on the next page,	I access; it with ZP,x addressing with x initially set; to 256.;	ldy #0	ldx #256loop	lda [Temp],y	sta TheDrawMask,x	inx	inx	iny	iny	cpy #MaskSize	bcc Loop	rtl	ENDP****************************************************************** ZP2UserMask** Moves the PenMask	from ZP to the area	pointed to by the user.*****************************************************************	EXPORT ZP2UserMaskZP2UserMask	PROCRTLAdr	equ 1OrigDirect	equ RTLAdr+3RTL1	equ OrigDirect+2RTL2	equ RTL1+3MaskPtr	equ RTL2+3	lda MaskPtr,s	; put low word of ptr in x	sta Temp	lda MaskPtr+1,s	; get med and high bytes	sta Temp+1;-----------------------------------------------;; Since TheFillPat is on the next page,	I access; it with ZP,x addressing with x initially set; to 256.;	ldy #0	ldx #256Loop	lda TheDrawMask,x	sta [Temp],y	inx	inx	iny	iny	cpy #MaskSize	bcc Loop	rtl	ENDP****************************************************************** ZP2Mask** Moves the penmask	on zero page to the	grafport*****************************************************************	EXPORT ZP2MaskZP2Mask	PROC	ldx #256	ldy #O_PnMaskLoop	lda TheDrawMask,x	sta [PortRef],y	iny	iny	inx	inx	cpx #MaskSize+256	bcc Loop	rtl	ENDP****************************************************************** Mask2ZP** Moves the penmask	in the grafport to zero page.*****************************************************************	EXPORT iMask2ZPiMask2ZP	PROC	ldx #256	ldy #O_PnMaskLoop	lda [PortRef],y	sta TheDrawMask,x	iny	iny	inx	inx	cpx #MaskSize+256	bcc Loop	rtl	ENDP****************************************************************** ExpandMask** Takes the mask on	zp and expands it from 1-bit per pixel* to n-bits per pixel.** The expanded mask	is stored already on zp.*****************************************************************	EXPORT iExpandMaskiExpandMask	PROC	bit PortSCB-1	bpl ExpandM320	jmp ExpandM640	ENDP****************************************************************** ExpandM320*****************************************************************	EXPORT ExpandM320ExpandM320	PROC	phd	tdc	clc	adc #$100	tcd	ldx #MaskSize-1Loop	lda TheDrawMask,x	jsr StuffMask320	dex	bpl Loop	pld	rtlStuffMask320		; 	phx	; save orig x	tay	; save orig byte	txa	; mult x by 4	asl a	; so this is index into expanded	asl a	; mask	pha	; put on stack	tya	; get byte back	and #$00FF	; mask of high word	asl a	; must by 4	asl a	tax	; convert	lda >ConTable320+2,x	tay	lda >ConTable320,x	plx	; get index off stack	sta TheDrawMask,x	inx	inx	tya	sta TheDrawMask,x	plx	; get orig x back	rts	ENDP****************************************************************** ExpandM640*****************************************************************	EXPORT ExpandM640ExpandM640	PROC	phd	tdc	clc	adc #$100	tcd	ldx #MaskSize-1Loop	lda TheDrawMask,x	jsr StuffMask640	dex	bpl Loop	pld	rtlStuffMask640		; 	phx	; save orig x	tay	; save orig byte	txa	; mult by 2	asl a	; so this is index into expanded mask	pha	; put on stack	tya	; get byte back	and #$00FF	; mask of high word	asl a	; must by 4	tax	; convert	lda >ConTable640,x	plx	; get index off stack	sta TheDrawMask,x	plx	rts	ENDP****************************************************************** RotateMask** Rotates TheDrawMask on zero page. The	amount to rotate is* passed in the a-register.** Modification History** 31 Dec 86    SEG**    This rotine was only rotating 8 bytes of the mask rather*    than the 32 bytes of the expanded mask!*** 08 Sep 88	Steven Glass** The 640 mode pattern is expanded to use the entire 32 bytes* of the pattern.  This means that code that uses the pattern* does not have to care what mode it is in.** 02 Oct 88	Steven Glass** Check the high bit of arc rot to see if we should* copy the 16 byte pattern into 32 bytes.** 18 May 89	Steven Glass** Undid change from 02 Oct.  Wonder what I was thinking.  It* cannot work that way since there will never be a 16 x 8 mask.*****************************************************************iRotateMask	PROC EXPORT	pha	; save the a-reg* Remove next three lines.  They are not needed.  There is no* such thing as a 16 x 8 mask.  SEG 18 May 89**	ldy #o_ArcRot	; look at high bit of ArcRot*	lda [PortRef],y*	bmi NoFutz	bit PortSCB-1	bpl NoFutz	phd	tdc	clc	adc #$100	tcd	lda TheDrawMask+14	sta TheDrawMask+28	sta TheDrawMask+30	lda TheDrawMask+12	sta TheDrawMask+24	sta TheDrawMask+26	lda TheDrawMask+10	sta TheDrawMask+20	sta TheDrawMask+22	lda TheDrawMask+8	sta TheDrawMask+16	sta TheDrawMask+18	lda TheDrawMask+6	sta TheDrawMask+12	sta TheDrawMask+14	lda TheDrawMask+4	sta TheDrawMask+8	sta TheDrawMask+10	lda TheDrawMask+2	sta TheDrawMask+4	sta TheDrawMask+6	lda TheDrawMask+0	sta TheDrawMask+2	pldNoFutz	pla	beq NeverMind	asl a	bit PortSCB-1	bmi Mode640	asl a	; bump this once more for 320 modeMode640	sta HowFarToShift	ldx #256	; use this in x since mask is*		; really on the next pageLoop	lda TheDrawMask+2,x	; get the current slice	tay	lda TheDrawMask,x	phx	; save x on stack	jsl RotateLong	; rotate it	plx	; get x back	sta TheDrawMask,x	, put the current slice back	tya	sta TheDrawMask+2,x	inx	; bump x and check to see if we	inx	; are done.	inx	inx	cpx #256+32	bcc LoopNeverMind	rtl	ENDP****************************************************************** RotateLong** Rotates the long passed in a & y and returns it an a & y.* The amount rotated is specified in HowFarToShift. The result* is returned in a & y.** All registers are	destroyed.** Modification History** 31 Dec 86    SEG**    Completely rewritten today and it now seems to work.  Earlier*    version may never have worked.*****************************************************************	EXPORT iRotateLongiRotateLong	PROC	xba	sta TEMP	tya	xba	sta TEMP+2	ldx HowFarToShift	beq DoneAgain	lda TEMP+2	; pick up high word	and rotate	asl a	; so can have carry	ready to shift	rol TEMP	; into low word here	rol TEMP+2	dex	; repeat until x = 0	bne AgainDone	lda TEMP+2	xba	tay	lda TEMP	xba	rtl	ENDP	END